from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.lte_rat_reset.classical_lte_rat_reset.lte_rat_reset_prototype import LteRatReset


class LteRatResetFactory(OperationFactoryPrototype):
    def __init__(self):
        super(LteRatResetFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for LTE rat reset operation.
        :return: dictionary with timeout, requirement and operation description for LTE rat reset
        :rtype: dict
        """
        return LteRatReset(self.bts).get_kpi()
